const payload = $json.body ?? $json;
const receipt = payload.receipt_id || payload.survey_id || 'unknown';
const pin = payload.intake_pin || payload.pin || '';
const triage = payload.triage_level || 'routine';
const gate = payload.send_gate || 'HOLD';
const lane = payload.notification_lane || payload.lane || 'internal_poc';
const isProbe = payload.event === 'patient_intake_notification_dry_v1';
const text = isProbe
  ? `[문진 PoC 프로브] gate=${gate} lane=${lane}`
  : `[한의원 사전 문진 접수]\n` +
    `접수 ID: ${receipt}\n` +
    `문진 PIN: ${pin || '(미발급)'}\n` +
    `트리아지: ${triage}\n` +
    `게이트: ${gate} / ${lane}\n` +
    `※ 내부 PoC · 대외 대량 발송 아님`;
return [{
  json: {
    ok: true,
    lane: 'patient_intake_notification',
    receipt_id: receipt,
    intake_pin: pin,
    triage_level: triage,
    send_gate: gate,
    notification_lane: lane,
    received_at_utc: new Date().toISOString(),
    text,
    skip_telegram: isProbe,
  },
}];
